      const target = path.join(dir, entry.name);
      if (entry.isDirectory()) await walk(target, `${relative}/`);
      else {
        const raw = await safeRead(target);
        files[relative] = decode(raw);
      }
    }
  }
  await walk(path.resolve(root));
  return files;
}

